<?php
require_once __DIR__.'/includes/module-shell.php';moduleReady('workspace_people',$user,'Organization');
// Internal directory intentionally excludes emails, contacts, dates of birth and documents.
$people=$db->query("SELECT u.id,u.full_name,p.department,p.job_title,p.location,p.is_demo,p.avatar_color FROM users u JOIN workspace_people p ON p.user_id=u.id WHERE u.role='employee' AND u.status='active' ORDER BY p.department,u.full_name")->fetchAll();$departments=[];foreach($people as $person)$departments[$person['department']][]=$person;moduleStart('Organization',$user);?>
<p style="margin-bottom:24px;color:var(--text-2)">Explore the team by department. This view shows work-directory information only.</p><div class="people-toolbar"><input class="form-control" id="organization-search" aria-label="Search organization" placeholder="Search people or departments"></div>
<?php foreach($departments as $department=>$members):?><section class="card organization-department" style="margin-bottom:24px"><div class="card-header"><h3><?=e($department)?></h3><span class="badge"><?=count($members)?> team members</span></div><div class="module-grid card-body"><?php foreach($members as $person):?><article class="person-card organization-person" data-search="<?=e(strtolower($person['full_name'].' '.$department.' '.$person['job_title'].' '.$person['location']))?>"><h3><?=e($person['full_name'])?></h3><p><?=e($person['job_title'])?></p><p><?=e($person['location'])?></p><?php if($person['is_demo']):?><p class="person-id">FICTIONAL DEMO PROFILE</p><?php endif;?><?php if($isAdmin):?><a class="btn btn-outline btn-sm" href="/admin/people.php?person=<?=(int)$person['id']?>" style="margin-top:15px">Open profile</a><?php endif;?></article><?php endforeach;?></div></section><?php endforeach;?><?php if(!$people):?><div class="card empty-state">Your team directory will appear when workplace details are assigned.</div><?php endif;moduleEnd();?><script src="/assets/js/organization.js"></script>
